#!/usr/bin/env node
/* eslint-disable no-console */
/**
 * sync-playbook-ids.js — dev-convenience copy of the backend's canonical
 * playbook-ids.generated.json into the frontend tree.
 *
 * Source of truth: backend `src/modules/ai/playbook-ids.generated.json`,
 * which is itself generated by `npm run export:playbook-ids` in the
 * backend repo. Do NOT hand-edit either file.
 *
 * Usage:
 *   BACKEND_REPO_PATH=/path/to/Cloudanzen-backend npm run sync:playbook-ids
 *
 * If `BACKEND_REPO_PATH` is unset, the script falls back to a sibling
 * checkout at `../Cloudanzen-backend`, which is the common local layout.
 *
 * CI does NOT call this. CI validates that the committed fixture in
 * this repo matches the frontend playbook registry (see vitest
 * `playbook-ids-parity.test.ts`). The cross-repo handoff is enforced
 * by the backend CI step that fails when the fixture drifts from
 * `PLAYBOOK_BASES`, prompting the contributor to open a matching
 * frontend PR.
 */

const fs = require('node:fs');
const path = require('node:path');

const backendRepo =
  process.env.BACKEND_REPO_PATH ||
  path.resolve(__dirname, '..', '..', 'Cloudanzen-backend');

const source = path.join(
  backendRepo,
  'src',
  'modules',
  'ai',
  'playbook-ids.generated.json',
);
const destination = path.resolve(
  __dirname,
  '..',
  'src',
  'app',
  'pages',
  'tests',
  'testDetail',
  'remediationPlaybooks',
  'playbook-ids.generated.json',
);

if (!fs.existsSync(source)) {
  console.error(
    `[sync-playbook-ids] Source fixture not found at ${source}.\n` +
      `Set BACKEND_REPO_PATH to your local Cloudanzen-backend checkout, or clone it as a sibling directory.`,
  );
  process.exit(1);
}

const contents = fs.readFileSync(source, 'utf8');
fs.writeFileSync(destination, contents, 'utf8');
console.log(`Synced ${source} → ${destination}`);
